cd /app && python3 -c "
import ipaddress
for s in ['fe80::1%eth0','1:2:3:4:5:6:7:8','12345::','::1%25eth0','0:0:0:0:0:0:0:1','::ffff:1.2.3.4','2001:db8::','1::2::3','a:b','::ffff:0.0.0.0','64:ff9b::1.2.3.4']:
    try:
        a = ipaddress.IPv6Address(s)
        print(repr(s), '->', a.compressed, '| scope:', getattr(a,'scope_id',None))
    except ValueError as e:
        print(repr(s), 'REJECT', e)
"
